CREATE TEMP TABLE catalogue_input ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"31f9e165-f9cc-5e37-81fd-87b51f16bff4","source_id":"0807","name_en":"suspended reverse crunch","name_ar":"\u0623\u0632\u0645\u0629 \u0639\u0643\u0633\u064a\u0629 \u0645\u0639\u0644\u0642\u0629","match_names":["suspended reverse crunch"],"muscle":"core","equipment":"bodyweight","aliases":["suspended reverse crunch"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Hang from a pull-up bar with your arms fully extended and your palms facing away from you.\nEngage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage.\nPause for a moment at the top, then slowly lower your knees back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0646 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0631\u0641\u0639 \u0631\u0643\u0628\u062a\u064a\u0643 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u062a\u062c\u0639\u064a\u062f \u062d\u0648\u0636\u0643 \u0646\u062d\u0648 \u0627\u0644\u0642\u0641\u0635 \u0627\u0644\u0635\u062f\u0631\u064a.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0807","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0807-R1WYG5D.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0807-R1WYG5D.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"133027ba-ab1a-5a3a-830e-c72ecffcdff9","source_id":"0808","name_en":"suspended row","name_ar":"\u0635\u0641 \u0645\u0639\u0644\u0642","match_names":["suspended row"],"muscle":"back","equipment":"bodyweight","aliases":["suspended row"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Set up a suspension trainer at an appropriate height.\nStand facing the anchor point with your feet shoulder-width apart.\nHold the handles with an overhand grip, palms facing each other.\nLean back, keeping your body straight and your heels on the ground.\nPull your chest towards the handles, squeezing your shoulder blades together.\nPause for a moment at the top, then slowly lower yourself back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0625\u0639\u062f\u0627\u062f \u0645\u062f\u0631\u0628 \u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0645\u0646\u0627\u0633\u0628.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0646\u0642\u0637\u0629 \u0627\u0644\u062a\u062b\u0628\u064a\u062a \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f\u060c \u0628\u062d\u064a\u062b \u062a\u0648\u0627\u062c\u0647 \u0631\u0627\u062d\u062a\u0627 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0627\u0633\u062a\u0646\u062f \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u062c\u0633\u0645\u0643 \u0648\u0643\u0639\u0628\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0627\u0633\u062d\u0628 \u0635\u062f\u0631\u0643 \u0646\u062d\u0648 \u0627\u0644\u0645\u0642\u0627\u0628\u0636\u060c \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0646\u0641\u0633\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0808","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0808-4OaumBr.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0808-4OaumBr.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e7aabf26-6b5c-5151-8994-f2350f13aab1","source_id":"0809","name_en":"suspended split squat","name_ar":"\u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0627\u0644\u0645\u0642\u0633\u0645 \u0627\u0644\u0645\u0639\u0644\u0642","match_names":["suspended split squat"],"muscle":"quads","equipment":"bodyweight","aliases":["suspended split squat"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand facing away from a suspension trainer with your feet shoulder-width apart.\nExtend one leg forward and place the top of your foot in the foot cradle of the suspension trainer.\nBend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes.\nPush through your heel to return to the starting position.\nRepeat for the desired number of repetitions, then switch legs.","steps_ar":"\u0642\u0641 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0645\u062f\u0631\u0628 \u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0645\u062f \u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629 \u0644\u0644\u0623\u0645\u0627\u0645 \u062b\u0645 \u0636\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0642\u062f\u0645\u0643 \u0641\u064a \u0645\u0647\u062f \u0627\u0644\u0642\u062f\u0645 \u0627\u0644\u062e\u0627\u0635 \u0628\u0645\u062f\u0631\u0628 \u0627\u0644\u062a\u0639\u0644\u064a\u0642.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0633\u0627\u0642\u0643 \u0627\u0644\u0648\u0627\u0642\u0641\u0629 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0641\u064a \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0648\u0631\u0643\u0628\u062a\u0643 \u0641\u064a \u0645\u062d\u0627\u0630\u0627\u0629 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643.\n\u0627\u062f\u0641\u0639 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0643\u0639\u0628\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0809","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0809-QpXqiq8.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0809-QpXqiq8.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"3db15d1b-7d2a-5c39-800a-d5d094b7f96d","source_id":"3433","name_en":"swimmer kicks v. 2 (male)","name_ar":"\u0631\u0643\u0644\u0627\u062a \u0627\u0644\u0633\u0628\u0627\u062d \u0627\u0644\u0625\u0635\u062f\u0627\u0631 2 (\u0630\u0643\u0631)","match_names":["swimmer kicks v. 2 (male)"],"muscle":"glutes","equipment":"bodyweight","aliases":["swimmer kicks v. 2 (male)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie face down on a mat with your arms extended overhead.\nEngage your core and lift your chest and legs off the ground simultaneously.\nKick your legs up and down in a fluttering motion, as if you were swimming.\nContinue kicking for the desired number of repetitions.\nLower your chest and legs back down to the starting position.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0648\u062c\u0647\u0643 \u0639\u0644\u0649 \u0627\u0644\u0633\u062c\u0627\u062f\u0629 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0639\u0644\u0649.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0631\u0641\u0639 \u0635\u062f\u0631\u0643 \u0648\u0633\u0627\u0642\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0641\u064a \u0648\u0642\u062a \u0648\u0627\u062d\u062f.\n\u0627\u0631\u0643\u0644 \u0633\u0627\u0642\u064a\u0643 \u0644\u0623\u0639\u0644\u0649 \u0648\u0644\u0623\u0633\u0641\u0644 \u0628\u062d\u0631\u0643\u0629 \u0631\u0641\u0631\u0641\u0629\u060c \u0643\u0645\u0627 \u0644\u0648 \u0643\u0646\u062a \u062a\u0633\u0628\u062d.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0631\u0643\u0644 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.\n\u0627\u062e\u0641\u0636 \u0635\u062f\u0631\u0643 \u0648\u0633\u0627\u0642\u064a\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3433","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3433-SP3hUez.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3433-SP3hUez.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"8951fa72-291b-516f-881e-3a4588122173","source_id":"3318","name_en":"swing 360","name_ar":"\u0633\u0648\u064a\u0646\u063a 360","match_names":["swing 360"],"muscle":"cardio","equipment":"bodyweight","aliases":["swing 360"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and knees slightly bent.\nHold your arms straight out in front of you, parallel to the ground.\nEngage your core and swing your arms in a circular motion, rotating your torso as you do so.\nContinue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions.\nRemember to breathe throughout the exercise.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0623\u0645\u0627\u0645\u0643\u060c \u0628\u0627\u0644\u062a\u0648\u0627\u0632\u064a \u0645\u0639 \u0627\u0644\u0623\u0631\u0636.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0623\u0631\u062c\u062d \u0630\u0631\u0627\u0639\u064a\u0643 \u0641\u064a \u062d\u0631\u0643\u0629 \u062f\u0627\u0626\u0631\u064a\u0629\u060c \u0648\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u062c\u0630\u0639\u0643 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0642\u064a\u0627\u0645 \u0628\u0630\u0644\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062d\u0631\u0643\u0629 \u0627\u0644\u062f\u0627\u0626\u0631\u064a\u0629\u060c \u0645\u0639 \u062a\u0623\u0631\u062c\u062d \u0630\u0631\u0627\u0639\u064a\u0643 \u0648\u062a\u062f\u0648\u064a\u0631 \u062c\u0630\u0639\u0643 \u0644\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.\n\u062a\u0630\u0643\u0631 \u0623\u0646 \u062a\u062a\u0646\u0641\u0633 \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3318","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"cardio","classification_status":"needs_review","source_target":"cardiovascular system","secondary_muscles":["shoulders","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3318-tnaj0mT.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3318-tnaj0mT.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"4e1231ee-3bbd-53e9-85ea-4f3f407ed02a","source_id":"1753","name_en":"three bench dip","name_ar":"\u062b\u0644\u0627\u062b\u0629 \u062a\u0631\u0627\u062c\u0639 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621","match_names":["three bench dip"],"muscle":"triceps","equipment":"bodyweight","aliases":["three bench dip"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on a bench with your hands gripping the edge, fingers pointing forward.\nSlide your butt off the bench, supporting your weight with your hands.\nBend your elbows and lower your body until your upper arms are parallel to the ground.\nPush yourself back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0625\u0645\u0633\u0627\u0643 \u064a\u062f\u064a\u0643 \u0628\u0627\u0644\u062d\u0627\u0641\u0629\u060c \u0648\u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u062d\u0631\u0643 \u0645\u0624\u062e\u0631\u062a\u0643 \u0645\u0646 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f\u060c \u0648\u0627\u062f\u0639\u0645 \u0648\u0632\u0646\u0643 \u0628\u064a\u062f\u064a\u0643.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u0627\u062f\u0641\u0639 \u0646\u0641\u0633\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1753","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1753-DQ0cqkT.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1753-DQ0cqkT.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"4fad7e8d-ddf5-5e9d-8a3a-c5e4a2f28759","source_id":"2459","name_en":"tire flip","name_ar":"\u0642\u0644\u0628 \u0627\u0644\u0625\u0637\u0627\u0631\u0627\u062a","match_names":["tire flip"],"muscle":"glutes","equipment":"tire","aliases":["tire flip"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart, facing the tire.\nBend your knees and hinge at the hips, lowering into a squat position.\nReach down and grab the bottom edge of the tire with both hands, fingers facing towards you.\nEngage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground.\nAs the tire flips over, use your upper body strength to guide it and maintain control.\nOnce the tire is fully flipped, quickly step back and reset your stance.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0625\u0637\u0627\u0631.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u062b\u0645 \u0627\u0646\u0632\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621.\n\u0642\u0645 \u0628\u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644 \u0648\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u062d\u0627\u0641\u0629 \u0627\u0644\u0633\u0641\u0644\u064a\u0629 \u0644\u0644\u0625\u0637\u0627\u0631 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0623\u0635\u0627\u0628\u0639 \u0646\u062d\u0648\u0643.\n\u0642\u0645 \u0628\u062a\u0634\u063a\u064a\u0644 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0648\u0627\u0644\u0633\u0627\u0642\u064a\u0646\u060c \u0648\u0642\u0645 \u0628\u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631 \u0639\u0628\u0631 \u0633\u0627\u0642\u064a\u0643 \u0644\u0631\u0641\u0639 \u0627\u0644\u0625\u0637\u0627\u0631 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636.\n\u0639\u0646\u062f\u0645\u0627 \u064a\u0646\u0642\u0644\u0628 \u0627\u0644\u0625\u0637\u0627\u0631\u060c \u0627\u0633\u062a\u062e\u062f\u0645 \u0642\u0648\u0629 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0644\u062a\u0648\u062c\u064a\u0647\u0647 \u0648\u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u062a\u062d\u0643\u0645 \u0641\u064a\u0647.\n\u0628\u0645\u062c\u0631\u062f \u0642\u0644\u0628 \u0627\u0644\u0625\u0637\u0627\u0631 \u0628\u0627\u0644\u0643\u0627\u0645\u0644\u060c \u062a\u0631\u0627\u062c\u0639 \u0633\u0631\u064a\u0639\u064b\u0627 \u0648\u0623\u0639\u062f \u0636\u0628\u0637 \u0648\u0636\u0639\u064a\u062a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2459","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2459-oZjMu1t.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2459-oZjMu1t.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e5b5e434-3141-5d93-84e4-6db78a20e2a2","source_id":"0811","name_en":"trap bar deadlift","name_ar":"\u0627\u0644\u0631\u0641\u0639\u0629 \u0627\u0644\u0645\u0645\u064a\u062a\u0629 \u0644\u0634\u0631\u064a\u0637 \u0627\u0644\u0641\u062e","match_names":["trap bar deadlift"],"muscle":"glutes","equipment":"trap_bar","aliases":["trap bar deadlift"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and the trap bar on the ground in front of you.\nBend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip.\nKeep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees.\nAs you lift, focus on driving through your heels and squeezing your glutes at the top of the movement.\nLower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0635\u064a\u062f\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0623\u0645\u0627\u0645\u0643.\n\u0627\u0646\u062d\u0646\u0649 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0644\u062e\u0641\u0636 \u0646\u0641\u0633\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u0627\u0644\u0625\u0645\u0633\u0627\u0643 \u0628\u0645\u0642\u0627\u0628\u0636 \u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0635\u064a\u062f\u0629 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0635\u062f\u0631\u0643 \u0644\u0623\u0639\u0644\u0649 \u0639\u0646\u062f\u0645\u0627 \u062a\u0628\u062f\u0623 \u0641\u064a \u0631\u0641\u0639 \u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0635\u064a\u062f\u0629 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646.\n\u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0631\u0641\u0639\u060c \u0631\u0643\u0632 \u0639\u0644\u0649 \u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0639\u0628\u0631 \u0643\u0639\u0628\u064a\u0643 \u0648\u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0635\u064a\u062f\u0629 \u0625\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0627\u0646\u062d\u0646\u0627\u0621 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0637\u0648\u0627\u0644 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0811","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0811-jQGwmxN.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0811-jQGwmxN.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"ebfbb60f-f366-5537-8beb-9653af2a5c98","source_id":"0814","name_en":"triceps dip","name_ar":"\u062a\u0631\u0627\u062c\u0639 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633","match_names":["triceps dip"],"muscle":"triceps","equipment":"bodyweight","aliases":["triceps dip"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.\nSlide your butt off the bench, supporting your weight with your hands.\nBend your elbows and lower your body towards the ground, keeping your back close to the bench.\nPause for a moment at the bottom, then push yourself back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u0627\u0644\u0645\u0642\u0639\u062f \u0623\u0648 \u0627\u0644\u0643\u0631\u0633\u064a \u0645\u0639 \u0625\u0645\u0633\u0627\u0643 \u064a\u062f\u064a\u0643 \u0628\u0627\u0644\u062d\u0627\u0641\u0629 \u0648\u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u062d\u0631\u0643 \u0645\u0624\u062e\u0631\u062a\u0643 \u0645\u0646 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f\u060c \u0648\u0627\u062f\u0639\u0645 \u0648\u0632\u0646\u0643 \u0628\u064a\u062f\u064a\u0643.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0638\u0647\u0631\u0643 \u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u0627\u0644\u0645\u0642\u0639\u062f.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0646\u0641\u0633\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{