u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u0638\u0647\u0631","match_names":["upper back stretch"],"muscle":"back","equipment":"bodyweight","aliases":["upper back stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand up straight with your feet shoulder-width apart.\nExtend your arms straight in front of you, parallel to the ground.\nInterlace your fingers and rotate your palms away from your body.\nSlowly raise your arms overhead, keeping them straight and parallel to each other.\nAs you raise your arms, squeeze your shoulder blades together.\nHold the stretch for 15-30 seconds, then release and repeat.","steps_ar":"\u0642\u0641 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0623\u0645\u0627\u0645\u0643\u060c \u0628\u0627\u0644\u062a\u0648\u0627\u0632\u064a \u0645\u0639 \u0627\u0644\u0623\u0631\u0636.\n\u0642\u0645 \u0628\u0634\u0628\u0643 \u0623\u0635\u0627\u0628\u0639\u0643 \u0648\u062a\u062f\u0648\u064a\u0631 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u062c\u0633\u0645\u0643.\n\u0627\u0631\u0641\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646 \u0648\u0645\u062a\u0648\u0627\u0632\u064a\u062a\u064a\u0646 \u0645\u0639 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0623\u062b\u0646\u0627\u0621 \u0631\u0641\u0639 \u0630\u0631\u0627\u0639\u064a\u0643\u060c \u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u064a\u0643 \u0645\u0639\u064b\u0627.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 15-30 \u062b\u0627\u0646\u064a\u0629\u060c \u062b\u0645 \u0627\u062a\u0631\u0643\u0647 \u0648\u0643\u0631\u0631 \u0627\u0644\u0623\u0645\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1365","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1365-GSDioYu.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1365-GSDioYu.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"d379d3da-9afc-58a7-8ce4-811011375a49","source_id":"1366","name_en":"upward facing dog","name_ar":"\u0643\u0644\u0628 \u0645\u0648\u0627\u062c\u0647 \u0644\u0644\u0623\u0639\u0644\u0649","match_names":["upward facing dog"],"muscle":"back","equipment":"bodyweight","aliases":["upward facing dog"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie face down on the floor with your legs extended behind you.\nPlace your hands on the floor next to your lower ribs, fingers pointing forward.\nPress your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground.\nRoll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling.\nHold this position for a few breaths, then slowly lower your body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0648\u062c\u0647\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u062e\u0644\u0641\u0643.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0628\u062c\u0648\u0627\u0631 \u0623\u0636\u0644\u0627\u0639\u0643 \u0627\u0644\u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0627\u0636\u063a\u0637 \u0628\u064a\u062f\u064a\u0643 \u0628\u0642\u0648\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0642\u0645 \u0628\u0641\u0631\u062f \u0630\u0631\u0627\u0639\u064a\u0643\u060c \u0648\u0627\u0631\u0641\u0639 \u062c\u0630\u0639\u0643 \u0648\u0641\u062e\u0630\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636.\n\u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0643 \u0643\u062a\u0641\u064a\u0643 \u0644\u0644\u062e\u0644\u0641 \u0648\u0644\u0644\u0623\u0633\u0641\u0644\u060c \u0648\u0627\u0641\u062a\u062d \u0635\u062f\u0631\u0643 \u0648\u0627\u0631\u0641\u0639 \u0646\u0638\u0631\u0643 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0628\u0636\u0639\u0629 \u0623\u0646\u0641\u0627\u0633\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1366","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"spine","secondary_muscles":["shoulders","chest"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1366-01qpYSe.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1366-01qpYSe.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"238b6edb-bd89-5522-87a0-31851d800954","source_id":"3420","name_en":"v-sit on floor","name_ar":"v-\u0627\u0644\u062c\u0644\u0648\u0633 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636","match_names":["v-sit on floor"],"muscle":"core","equipment":"bodyweight","aliases":["v-sit on floor"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the floor with your legs extended in front of you.\nLean back slightly and lift your legs off the ground, keeping them straight.\nSimultaneously, lift your upper body off the ground and reach your arms towards your legs.\nHold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u0623\u0645\u0627\u0645\u0643.\n\u0627\u0646\u062d\u0646\u0650 \u0644\u0644\u062e\u0644\u0641 \u0642\u0644\u064a\u0644\u0627\u064b \u0648\u0627\u0631\u0641\u0639\u064a \u0633\u0627\u0642\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646.\n\u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0648\u0642\u062a\u060c \u0627\u0631\u0641\u0639\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u062f\u064a \u0630\u0631\u0627\u0639\u064a\u0643 \u0646\u062d\u0648 \u0633\u0627\u0642\u064a\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0648\u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3420","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3420-ZuXu4Eq.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3420-ZuXu4Eq.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"ede4118d-b6c1-51a9-845e-1a1e33c8e116","source_id":"0826","name_en":"vertical leg raise (on parallel bars)","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u0633\u0627\u0642 \u0639\u0645\u0648\u062f\u064a\u064b\u0627 (\u0639\u0644\u0649 \u0627\u0644\u0642\u0636\u0628\u0627\u0646 \u0627\u0644\u0645\u062a\u0648\u0627\u0632\u064a\u0629)","match_names":["vertical leg raise (on parallel bars)"],"muscle":"core","equipment":"bodyweight","aliases":["vertical leg raise (on parallel bars)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Hang from the parallel bars with your arms fully extended and your body straight.\nEngage your core and lift your legs up in front of you, keeping them straight.\nContinue lifting until your legs are parallel to the ground or slightly higher.\nPause for a moment at the top, then slowly lower your legs back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0634\u0646\u0642 \u0645\u0646 \u0627\u0644\u0642\u0636\u0628\u0627\u0646 \u0627\u0644\u0645\u062a\u0648\u0627\u0632\u064a\u0629 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u062a\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u062c\u0633\u0645\u0643 \u0645\u0633\u062a\u0642\u064a\u0645.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0623\u0645\u0627\u0645\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0631\u0641\u0639 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0633\u0627\u0642\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u0629 \u0644\u0644\u0623\u0631\u0636 \u0623\u0648 \u0623\u0639\u0644\u0649 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0826","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0826-ZNgOYQU.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0826-ZNgOYQU.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"53d225d5-22e0-59e4-8f4e-70f922e1bc5e","source_id":"2141","name_en":"walk elliptical cross trainer","name_ar":"\u0627\u0644\u0645\u0634\u064a \u0639\u0628\u0631 \u0645\u062f\u0631\u0628 \u0628\u064a\u0636\u0627\u0648\u064a \u0627\u0644\u0634\u0643\u0644","match_names":["walk elliptical cross trainer"],"muscle":"cardio","equipment":"elliptical_machine","aliases":["walk elliptical cross trainer"],"logging_mode":"timed","load_convention":"external_total","guidance":{"steps_en":"Adjust the resistance level and incline of the elliptical machine to your desired settings.\nStep onto the pedals of the machine and grip the handles lightly.\nBegin by pushing down with your feet and pulling the handles towards your body.\nContinue this motion, alternating between pushing and pulling, to simulate a walking or running motion.\nMaintain a steady pace and keep your core engaged throughout the exercise.\nContinue for the desired duration of your cardio workout.\nGradually decrease the intensity and speed of the machine before stepping off.","steps_ar":"\u0627\u0636\u0628\u0637 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0648\u0627\u0646\u062d\u062f\u0627\u0631 \u0627\u0644\u0622\u0644\u0629 \u0627\u0644\u0628\u064a\u0636\u0627\u0648\u064a\u0629 \u062d\u0633\u0628 \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u0631\u064a\u062f\u0647\u0627.\n\u0642\u0645 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0639\u0644\u0649 \u062f\u0648\u0627\u0633\u0627\u062a \u0627\u0644\u0622\u0644\u0629 \u0648\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0631\u0641\u0642.\n\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0636\u063a\u0637 \u0628\u0642\u062f\u0645\u064a\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u0633\u062d\u0628 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0646\u062d\u0648 \u062c\u0633\u0645\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062f\u0641\u0639 \u0648\u0627\u0644\u0633\u062d\u0628\u060c \u0644\u0645\u062d\u0627\u0643\u0627\u0629 \u062d\u0631\u0643\u0629 \u0627\u0644\u0645\u0634\u064a \u0623\u0648 \u0627\u0644\u062c\u0631\u064a.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0648\u062a\u064a\u0631\u0629 \u062b\u0627\u0628\u062a\u0629 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0646\u0634\u0627\u0637\u0643 \u0627\u0644\u0623\u0633\u0627\u0633\u064a \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u0645\u062f\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629 \u0645\u0646 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0642\u0644\u0628.\n\u0642\u0645 \u0628\u062a\u0642\u0644\u064a\u0644 \u0643\u062b\u0627\u0641\u0629 \u0648\u0633\u0631\u0639\u0629 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629 \u062a\u062f\u0631\u064a\u062c\u064a\u064b\u0627 \u0642\u0628\u0644 \u0627\u0644\u0646\u0632\u0648\u0644 \u0645\u0646\u0647\u0627.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2141","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"cardio","classification_status":"needs_review","source_target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2141-rjtuP6X.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2141-rjtuP6X.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"80dd16b6-d800-5f99-863f-b8f301a92637","source_id":"3655","name_en":"walking high knees lunge","name_ar":"\u0627\u0644\u0645\u0634\u064a \u0628\u0631\u0643\u0628\u062a\u064a\u0646 \u0639\u0627\u0644\u064a\u062a\u064a\u0646","match_names":["walking high knees lunge"],"muscle":"cardio","equipment":"bodyweight","aliases":["walking high knees lunge"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet hip-width apart.\nLift your right knee up towards your chest as high as you can while balancing on your left leg.\nStep forward with your right foot and lower your body into a lunge position, bending both knees to a 90-degree angle.\nPush off with your right foot and bring your left knee up towards your chest.\nStep forward with your left foot and lower your body into a lunge position.\nContinue alternating legs and lunging forward, keeping your core engaged and maintaining a steady pace.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0639\u0631\u0636 \u0645\u0641\u0635\u0644 \u0627\u0644\u0648\u0631\u0643.\n\u0627\u0631\u0641\u0639 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0645\u0643\u0646 \u0628\u064a\u0646\u0645\u0627 \u062a\u0648\u0627\u0632\u0646 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u062a\u0642\u062f\u0645 \u0644\u0644\u0623\u0645\u0627\u0645 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639\u060c \u0645\u0639 \u062b\u0646\u064a \u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0627\u062f\u0641\u0639 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0627\u0631\u0641\u0639 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643.\n\u062a\u0642\u062f\u0645 \u0644\u0644\u0623\u0645\u0627\u0645 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0623\u0631\u062c\u0644 \u0648\u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0646\u0634\u0627\u0637 \u0627\u0644\u062c\u0630\u0639 \u0648\u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0648\u062a\u064a\u0631\u0629 \u062b\u0627\u0628\u062a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3655","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"cardio","classification_status":"needs_review","source_target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3655-J9zIWig.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3655-J9zIWig.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"01aac1d3-12c0-526b-8a16-3978c10c2bb0","source_id":"1460","name_en":"walking lunge","name_ar":"\u0627\u0646\u062f\u0641\u0627\u0639 \u0627\u0644\u0645\u0634\u064a","match_names":["walking lunge"],"muscle":"glutes","equipment":"bodyweight","aliases":["walking lunge"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart.\nTake a step forward with your right leg, lowering your body into a lunge position.\nKeep your torso upright and your front knee aligned with your ankle.\nPush off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg.\nContinue alternating legs and walking forward, maintaining a controlled and steady pace.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u062a\u062e\u0630 \u062e\u0637\u0648\u0629 \u0644\u0644\u0623\u0645\u0627\u0645 \u0628\u0631\u062c\u0644\u0643 \u0627\u0644\u064a\u0645\u0646\u0649\u060c \u0648\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u062c\u0630\u0639\u0643 \u0648\u0645\u062d\u0627\u0630\u0627\u0629 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u0623\u0645\u0627\u0645\u064a\u0629 \u0645\u0639 \u0643\u0627\u062d\u0644\u0643.\n\u0627\u062f\u0641\u0639 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0627\u062f\u0641\u0639 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u062b\u0645 \u0627\u062a\u062e\u0630 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639 \u0628\u0631\u062c\u0644\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0623\u0631\u062c\u0644 \u0648\u0627\u0644\u0645\u0634\u064a \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0648\u062a\u064a\u0631\u0629 \u062b\u0627\u0628\u062a\u0629 \u0648\u0645\u0646\u0636\u0628\u0637\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1460","license":"MIT"},"translation":{"provider":"Google Tra