\u0649 \u0627\u0644\u062f\u0631\u062c\u0629 \u062b\u0645 \u0627\u0644\u0623\u062e\u0631\u0649\u060c \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u0633\u0627\u0642\u064a\u0646.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0648\u0636\u0639 \u0645\u0633\u062a\u0642\u064a\u0645 \u0648\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a\u0643 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0645\u0634\u064a \u0644\u0644\u0645\u062f\u0629 \u0623\u0648 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629.\n\u0642\u0645 \u0628\u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u0634\u062f\u0629 \u0623\u0648 \u0627\u0644\u0633\u0631\u0639\u0629 \u062a\u062f\u0631\u064a\u062c\u064a\u064b\u0627 \u0639\u0646\u062f\u0645\u0627 \u062a\u0635\u0628\u062d \u0623\u0643\u062b\u0631 \u0631\u0627\u062d\u0629 \u0641\u064a \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u062a\u0630\u0643\u0631 \u0623\u0646 \u062a\u0647\u062f\u0623 \u0648\u062a\u0645\u062a\u062f \u0628\u0639\u062f \u0627\u0644\u0627\u0646\u062a\u0647\u0627\u0621 \u0645\u0646 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2311","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"cardio","classification_status":"needs_review","source_target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2311-j9Q5crt.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2311-j9Q5crt.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"a92d44b4-f192-519a-8228-70806d87a933","source_id":"0830","name_en":"weighted bench dip","name_ar":"\u062a\u0631\u0627\u062c\u0639 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621 \u0627\u0644\u0645\u0631\u062c\u062d\u0629","match_names":["weighted bench dip"],"muscle":"triceps","equipment":"weighted","aliases":["weighted bench dip"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on a bench with your hands gripping the edge, fingers pointing forward.\nSlide your butt off the bench, supporting your weight with your hands.\nLower your body by bending your elbows until your upper arms are parallel to the floor.\nPush yourself back up to the starting position by straightening your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0625\u0645\u0633\u0627\u0643 \u064a\u062f\u064a\u0643 \u0628\u0627\u0644\u062d\u0627\u0641\u0629\u060c \u0648\u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u062d\u0631\u0643 \u0645\u0624\u062e\u0631\u062a\u0643 \u0645\u0646 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f\u060c \u0648\u0627\u062f\u0639\u0645 \u0648\u0632\u0646\u0643 \u0628\u064a\u062f\u064a\u0643.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u0627\u062f\u0641\u0639 \u0646\u0641\u0633\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0641\u0631\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0830","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0830-MU9HnE7.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0830-MU9HnE7.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"36607f7c-4819-5ec7-8ed2-a6bfec5cb137","source_id":"2987","name_en":"weighted close grip chin-up on dip cage","name_ar":"\u0642\u0628\u0636\u0629 \u0645\u062d\u0643\u0645\u0629 \u0645\u0631\u062c\u062d\u0629 \u0639\u0644\u0649 \u0642\u0641\u0635 \u0627\u0644\u063a\u0637\u0633","match_names":["weighted close grip chin-up on dip cage"],"muscle":"back","equipment":"weighted","aliases":["weighted close grip chin-up on dip cage"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.\nHang from the bars with your arms fully extended, feet off the ground, and body straight.\nEngage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides.\nContinue pulling until your chin is above the bars, then pause for a moment.\nSlowly lower your body back down to the starting position, fully extending your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0623\u0645\u0627\u0645 \u0642\u0641\u0635 \u0627\u0644\u063a\u0637\u0633 \u0648\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u0642\u0636\u064a\u0628\u064a\u0646 \u0627\u0644\u0645\u062a\u0648\u0627\u0632\u064a\u064a\u0646 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0634\u0646\u0642 \u0645\u0646 \u0627\u0644\u0642\u0636\u0628\u0627\u0646 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0631\u0641\u0648\u0639\u062a\u064a\u0646 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u062c\u0633\u0645\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0638\u0647\u0631\u0643 \u0648\u0627\u0633\u062d\u0628 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0627\u0644\u0642\u0636\u0628\u0627\u0646\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0633\u062d\u0628 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0630\u0642\u0646\u0643 \u0641\u0648\u0642 \u0627\u0644\u0642\u0636\u0628\u0627\u0646\u060c \u062b\u0645 \u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629.\n\u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637