drm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0832-s8nrDXF.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c79566fc-d96a-5bfe-8378-da3914a75493","source_id":"3670","name_en":"weighted decline sit-up","name_ar":"\u062a\u0631\u0627\u062c\u0639 \u0627\u0644\u0645\u0631\u062c\u062d \u0627\u0644\u0627\u0639\u062a\u0635\u0627\u0645","match_names":["weighted decline sit-up"],"muscle":"core","equipment":"weighted","aliases":["weighted decline sit-up"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Lie flat on a decline bench with your feet secured under the foot pads.\nPlace your hands behind your head or across your chest.\nEngage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.\nPause for a moment at the top, then slowly lower your upper body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u0650 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0646\u062d\u062f\u0631 \u0645\u0639 \u062a\u062b\u0628\u064a\u062a \u0642\u062f\u0645\u064a\u0643 \u0623\u0633\u0641\u0644 \u0648\u0633\u0627\u062f\u0627\u062a \u0627\u0644\u0642\u062f\u0645.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0623\u0648 \u0639\u0628\u0631 \u0635\u062f\u0631\u0643.\n\u0642\u0645 \u0628\u062a\u0634\u063a\u064a\u0644 \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643 \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0639\u0646 \u0627\u0644\u0645\u0642\u0639\u062f\u060c \u062b\u0645 \u0642\u0645 \u0628\u0627\u0644\u0627\u0646\u062d\u0646\u0627\u0621 \u0644\u0644\u0623\u0645\u0627\u0645 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u062c\u0630\u0639\u0643 \u0639\u0645\u0648\u062f\u064a\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3670","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3670-EZeDVzO.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3670-EZeDVzO.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"16c3a694-bd11-5f64-8840-d45e65f2c895","source_id":"0833","name_en":"weighted donkey calf raise","name_ar":"\u0631\u0641\u0639 \u0639\u062c\u0644 \u0627\u0644\u062d\u0645\u0627\u0631 \u0627\u0644\u0645\u0631\u062c\u062d","match_names":["weighted donkey calf raise"],"muscle":"calves","equipment":"weighted","aliases":["weighted donkey calf raise"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand on a raised platform with your toes on the edge and your heels hanging off.\nHold onto a stable object for support.\nRaise your heels as high as possible by extending your ankles.\nPause for a moment at the top, then slowly lower your heels back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0639\u0644\u0649 \u0645\u0646\u0635\u0629 \u0645\u0631\u062a\u0641\u0639\u0629 \u0645\u0639 \u0648\u0636\u0639 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0641\u0629 \u0648\u0643\u0639\u0628\u064a\u0643 \u0645\u0639\u0644\u0642\u064a\u0646.\n\u0627\u0644\u062a\u0645\u0633\u0643 \u0628\u062c\u0633\u0645 \u0645\u0633\u062a\u0642\u0631 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0627\u0631\u0641\u0639\u064a \u0643\u0639\u0628\u064a\u0643 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0645\u0643\u0646 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u0645\u062f\u064a\u062f \u0643\u0627\u062d\u0644\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0643\u0639\u0628\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0833","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["hamstrings","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0833-LmaFNZS.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0833-LmaFNZS.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"1b30eb84-b80e-54c7-8574-565615614c0c","source_id":"1310","name_en":"weighted drop push up","name_ar":"\u062f\u0641\u0639 \u0642\u0637\u0631\u0629 \u0645\u0631\u062c\u062d\u0629 \u0644\u0623\u0639\u0644\u0649","match_names":["weighted drop push up"],"muscle":"chest","equipment":"weighted","aliases":["weighted drop push up"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.\nLower your chest towards the ground, keeping your elbows close to your body.\nOnce your chest is just above the ground, explosively push yourself up, lifting your hands off the ground.\nAs you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground.\nCatch yourself with your hands in the wider position and immediately lower your chest towards the ground again.\nRepeat the push-up motion, dropping down and catching yourself with your hands in the narrower position.\nContinue alternating between the wider and narrower hand positions for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0641\u064a \u0648\u0636\u0639 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062e\u0634\u0628\u064a \u0627\u0644\u0645\u0631\u062a\u0641\u0639 \u0645\u0639 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0645\u0633\u0627\u0641\u0629 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u0627\u064b \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0639\u064b\u0627.\n\u0627\u062e\u0641\u0636 \u0635\u062f\u0631\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u0628\u0645\u062c\u0631\u062f \u0623\u0646 \u064a\u0635\u0628\u062d \u0635\u062f\u0631\u0643 \u0641\u0648\u0642 \u0627\u0644\u0623\u0631\u0636 \u0645\u0628\u0627\u0634\u0631\u0629\u064b\u060c \u0627\u062f\u0641\u0639 \u0646\u0641\u0633\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631\u060c \u0648\u0627\u0631\u0641\u0639 \u064a\u062f\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062f\u0641\u0639 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u062d\u0631\u0643 \u064a\u062f\u064a\u0643 \u0628\u0633\u0631\u0639\u0629 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0648\u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0642\u0644\u064a\u0644\u0627\u064b\u060c \u0645\u0645\u0627 \u064a\u0633\u0645\u062d \u0644\u062c\u0633\u0645\u0643 \u0628\u0627\u0644\u0647\u0628\u0648\u0637 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0646\u0641\u0633\u0643 \u0628\u064a\u062f\u064a\u0643 \u0641\u064a \u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0623\u0648\u0633\u0639 \u0648\u0642\u0645 \u0628\u062e\u0641\u0636 \u0635\u062f\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0641\u0648\u0631 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649.\n\u0643\u0631\u0631 \u062d\u0631\u0643\u0629 \u0627\u0644\u0636\u063a\u0637 \u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u0646\u0632\u0644 \u0644\u0644\u0623\u0633\u064